#!/usr/bin/env bash
set -Eeuo pipefail
cd "$(dirname "$0")/.."
T="$(mktemp -d)"
trap 'rm -rf -- "$T"' EXIT
# Run the real Java engines against immutable label fixtures generated by the supplied JS reference.
javac -J-Xmx1000m -sourcepath app/src/main/java:tests:tests/android-host-stubs -d "$T" \
  tests/android-host-stubs/android/graphics/{Bitmap,Canvas,Paint,Path}.java \
  tests/V3AllStyleExportMatrixTest.java tests/V3PopPosterStylesTest.java \
  tests/V3PopPosterPortParityTest.java tests/V3PopPosterCutAudit.java \
  tests/V3StyleSelectionCrashRegressionTest.java
java -ea -Xmx1300m -cp "$T" com.halftonestudio.V3StyleSelectionCrashRegressionTest
java -ea -Xmx1300m -cp "$T" com.halftonestudio.V3PopPosterPortParityTest tests/fixtures/pop-poster
java -ea -Xmx1300m -cp "$T" com.halftonestudio.V3PopPosterStylesTest
for size in 76.2 101.6 279.4; do
  java -ea -Xmx1300m -cp "$T" com.halftonestudio.V3PopPosterCutAudit "$size"
done
python3 tests/check-v3-pop-poster-integration.py
